apiVersion: v1
kind: Namespace
metadata:
  name: demo
---
apiVersion: v1
kind: ConfigMap
metadata:
  name: app-src
  namespace: demo
data:
  pom.xml: |
    <?xml version="1.0" encoding="UTF-8"?>
    <project xmlns="http://maven.apache.org/POM/4.0.0"
             xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
             xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 https://maven.apache.org/xsd/maven-4.0.0.xsd">
      <modelVersion>4.0.0</modelVersion>
      <parent>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-parent</artifactId>
        <version>3.5.6</version>
        <relativePath/>
      </parent>
      <groupId>lab</groupId>
      <artifactId>app</artifactId>
      <version>1.0.0</version>
      <properties>
        <java.version>21</java.version>
      </properties>
      <dependencyManagement>
        <dependencies>
          <dependency>
            <groupId>io.awspring.cloud</groupId>
            <artifactId>spring-cloud-aws-dependencies</artifactId>
            <version>3.4.0</version>
            <type>pom</type>
            <scope>import</scope>
          </dependency>
        </dependencies>
      </dependencyManagement>
      <dependencies>
        <dependency>
          <groupId>org.springframework.boot</groupId>
          <artifactId>spring-boot-starter-web</artifactId>
        </dependency>
        <dependency>
          <groupId>io.awspring.cloud</groupId>
          <artifactId>spring-cloud-aws-starter-sqs</artifactId>
        </dependency>
      </dependencies>
      <build>
        <finalName>app</finalName>
        <plugins>
          <plugin>
            <groupId>org.springframework.boot</groupId>
            <artifactId>spring-boot-maven-plugin</artifactId>
          </plugin>
        </plugins>
      </build>
    </project>
  App.java: |
    package lab;

    import io.awspring.cloud.sqs.annotation.SqsListener;
    import io.awspring.cloud.sqs.operations.SqsTemplate;
    import java.util.Map;
    import org.slf4j.Logger;
    import org.slf4j.LoggerFactory;
    import org.springframework.beans.factory.annotation.Value;
    import org.springframework.boot.SpringApplication;
    import org.springframework.boot.autoconfigure.SpringBootApplication;
    import org.springframework.context.annotation.Profile;
    import org.springframework.stereotype.Component;
    import org.springframework.web.bind.annotation.PathVariable;
    import org.springframework.web.bind.annotation.PostMapping;
    import org.springframework.web.bind.annotation.RestController;

    // One jar, two services. The profile picks which one runs, and there is no tracing code in either.
    @SpringBootApplication
    public class App {
      public static void main(String[] args) {
        SpringApplication.run(App.class, args);
      }

      @RestController
      @Profile("orders")
      public static class Orders {
        private final SqsTemplate sqs;
        private final String queue;

        public Orders(SqsTemplate sqs, @Value("${queue.name}") String queue) {
          this.sqs = sqs;
          this.queue = queue;
        }

        @PostMapping("/orders/{id}")
        public Map<String, Object> order(@PathVariable("id") long id) {
          String messageId = sqs.send(queue, "order-" + id).messageId().toString();
          return Map.of("order", id, "messageId", messageId);
        }
      }

      @Component
      @Profile("fulfilment")
      public static class Fulfilment {
        private static final Logger log = LoggerFactory.getLogger(Fulfilment.class);

        @SqsListener("${queue.name}")
        public void handle(String body) {
          log.info("fulfilled {}", body);
        }
      }
    }
---
# Builds the jar once and fetches the agent once. Both land on the app node, so every run uses the same files.
apiVersion: batch/v1
kind: Job
metadata:
  name: build
  namespace: demo
spec:
  backoffLimit: 0
  activeDeadlineSeconds: 420
  template:
    spec:
      restartPolicy: Never
      nodeName: APP_NODE
      volumes:
        - name: src
          configMap:
            name: app-src
        - name: lab
          hostPath:
            path: /opt/lab
            type: DirectoryOrCreate
      initContainers:
        - name: fetch-agent
          image: python:3.12-slim
          volumeMounts:
            - { name: lab, mountPath: /lab }
          command:
            - python
            - -c
            - |
              import time, urllib.request
              url = "https://github.com/open-telemetry/opentelemetry-java-instrumentation/releases/download/v2.33.1/opentelemetry-javaagent.jar"
              for attempt in range(1, 13):
                  try:
                      urllib.request.urlretrieve(url, "/lab/opentelemetry-javaagent.jar")
                      print("agent downloaded on attempt", attempt)
                      break
                  except Exception as e:
                      print("download attempt", attempt, "failed:", e)
                      time.sleep(10)
              else:
                  raise SystemExit("the agent could not be downloaded")
      containers:
        - name: build
          image: maven:3.9.9-eclipse-temurin-21
          volumeMounts:
            - { name: src, mountPath: /src }
            - { name: lab, mountPath: /lab }
          command:
            - sh
            - -c
            - |
              set -e
              mkdir -p /w/src/main/java/lab
              cp /src/pom.xml /w/pom.xml
              cp /src/App.java /w/src/main/java/lab/App.java
              cd /w
              mvn -q -B -DskipTests package
              cp target/app.jar /lab/app.jar
              ls -l /lab

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80"
    }
  }
}

locals {
  k8s_version = "1.34"
  node_count  = 2
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "ami" {
  name = "/aws/service/eks/optimized-ami/${local.k8s_version}/amazon-linux-2023/x86_64/standard/recommended/image_id"
}

# ---------------- network (public subnets only, no NAT) ----------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = { Name = "${var.lab_name}-vpc" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${var.lab_name}-igw" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true
  tags                    = { Name = "${var.lab_name}-public-${count.index}" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "${var.lab_name}-public" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------- IAM ----------------
resource "aws_iam_role" "cluster" {
  name                 = "hero-lab-${var.lab_name}-cluster"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "eks.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "node" {
  name                 = "hero-lab-${var.lab_name}-node"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "ec2.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node" {
  for_each = toset([
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
  ])
  role       = aws_iam_role.node.name
  policy_arn = each.value
}

# The pipeline role only allows IAM resources named hero-lab-*, so the instance profile carries that prefix too.
resource "aws_iam_instance_profile" "node" {
  name = "hero-lab-${var.lab_name}-node"
  role = aws_iam_role.node.name
}

# ---------------- the queue, and the role the pods use to reach it ----------------
resource "aws_sqs_queue" "orders" {
  name                       = "${var.lab_name}-orders"
  visibility_timeout_seconds = 30
  message_retention_seconds  = 3600
}

resource "aws_iam_role" "sqs" {
  name                 = "hero-lab-${var.lab_name}-sqs"
  permissions_boundary = var.permissions_boundary
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = ["sts:AssumeRole", "sts:TagSession"]
      Principal = { Service = "pods.eks.amazonaws.com" }
    }]
  })
}

# The calls Spring Cloud AWS makes, on this one queue.
resource "aws_iam_role_policy" "sqs" {
  name = "${var.lab_name}-sqs-orders"
  role = aws_iam_role.sqs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "sqs:GetQueueUrl",
        "sqs:GetQueueAttributes",
        "sqs:SendMessage",
        "sqs:ReceiveMessage",
        "sqs:DeleteMessage",
        "sqs:ChangeMessageVisibility",
      ]
      Resource = aws_sqs_queue.orders.arn
    }]
  })
}

# ---------------- EKS control plane ----------------
resource "aws_eks_cluster" "main" {
  name     = var.lab_name
  role_arn = aws_iam_role.cluster.arn
  version  = local.k8s_version

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_public_access  = true
    endpoint_private_access = false
  }

  access_config {
    authentication_mode                         = "API"
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [aws_iam_role_policy_attachment.cluster]
}

resource "aws_eks_access_entry" "node" {
  cluster_name  = aws_eks_cluster.main.name
  principal_arn = aws_iam_role.node.arn
  type          = "EC2_LINUX"
}

# ---------------- self-managed nodes joined with nodeadm ----------------
locals {
  user_data = <<-EOT
    MIME-Version: 1.0
    Content-Type: multipart/mixed; boundary="BOUNDARY"

    --BOUNDARY
    Content-Type: application/node.eks.aws

    ---
    apiVersion: node.eks.aws/v1alpha1
    kind: NodeConfig
    spec:
      cluster:
        name: ${aws_eks_cluster.main.name}
        apiServerEndpoint: ${aws_eks_cluster.main.endpoint}
        certificateAuthority: ${aws_eks_cluster.main.certificate_authority[0].data}
        cidr: ${aws_eks_cluster.main.kubernetes_network_config[0].service_ipv4_cidr}

    --BOUNDARY--
  EOT
}

resource "aws_instance" "node" {
  count                       = local.node_count
  ami                         = nonsensitive(data.aws_ssm_parameter.ami.value)
  instance_type               = "t3.large"
  subnet_id                   = aws_subnet.public[count.index % 2].id
  iam_instance_profile        = aws_iam_instance_profile.node.name
  vpc_security_group_ids      = [aws_eks_cluster.main.vpc_config[0].cluster_security_group_id]
  associate_public_ip_address = true
  user_data                   = local.user_data

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  root_block_device {
    volume_size = 30
    volume_type = "gp3"
  }

  tags = { Name = "${var.lab_name}-node-${count.index}" }

  depends_on = [aws_eks_access_entry.node, aws_iam_role_policy_attachment.node]
}

# ---------------- EKS Pod Identity for the sqs-lab service account ----------------
resource "aws_eks_addon" "pod_identity" {
  cluster_name                = aws_eks_cluster.main.name
  addon_name                  = "eks-pod-identity-agent"
  resolve_conflicts_on_create = "OVERWRITE"
  depends_on                  = [aws_instance.node]
}

resource "aws_eks_pod_identity_association" "sqs" {
  cluster_name    = aws_eks_cluster.main.name
  namespace       = "demo"
  service_account = "sqs-lab"
  role_arn        = aws_iam_role.sqs.arn
  depends_on      = [aws_eks_addon.pod_identity]
}

output "cluster_name" {
  value = aws_eks_cluster.main.name
}

output "queue_name" {
  value = aws_sqs_queue.orders.name
}

output "queue_url" {
  value = aws_sqs_queue.orders.url
}
